&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1582&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH CasierMap AS
(
    SELECT
        LTRIM(RTRIM(CodSucursala)) AS CodSucursala,
        LTRIM(RTRIM(CodPlata)) AS CodPlata,
        MAX(CodCasier) AS CodCasier
    FROM app.CasierPlatitor
    WHERE LTRIM(RTRIM(CodSucursala))
        = LTRIM(RTRIM(@CodSucursala))
    GROUP BY
        LTRIM(RTRIM(CodSucursala)),
        LTRIM(RTRIM(CodPlata))
),
Organigrama AS
(
    SELECT
        LTRIM(RTRIM(CodSucursala)) AS CodSucursala,
        LTRIM(RTRIM(CodInferior)) AS CodPlata,
        MAX(NULLIF(LTRIM(RTRIM(DenumireInferior)), &#39;&#39;)) AS LocPlata
    FROM app.NomOrganigrama
    WHERE LTRIM(RTRIM(CodSucursala))
        = LTRIM(RTRIM(@CodSucursala))
      AND Anul = @Anul
      AND Luna = @Luna
    GROUP BY
        LTRIM(RTRIM(CodSucursala)),
        LTRIM(RTRIM(CodInferior))
),
Baza AS
(
    SELECT
        cl.Id AS CalculLichidareId,
        LTRIM(RTRIM(cl.CodSucursala)) AS CodSucursala,
        NULLIF(LTRIM(RTRIM(s.CodPlata)), &#39;&#39;) AS CodPlata,
        LTRIM(RTRIM(cl.Marca)) AS Marca,

        COALESCE(
            NULLIF(LTRIM(RTRIM(s.Nume)), &#39;&#39;),
            NULLIF(LTRIM(RTRIM(cl.Nume)), &#39;&#39;)
        ) AS Nume,

        CAST(
            ISNULL(cl.NetdePlata, 0)
            AS decimal(18, 2)
        ) AS NetdePlata,

        sc.Denumire AS StatusCalcul
    FROM app.CalculLichidare cl
    INNER JOIN app.Salariat s
        ON s.Id = cl.IdSalariat
       AND s.CodSucursala = cl.CodSucursala
       AND s.Anul = cl.Anul
       AND s.Luna = cl.Luna
    LEFT JOIN app.StatusCalcul sc
        ON sc.Id = cl.Status
    WHERE cl.CodSucursala = @CodSucursala
      AND cl.Anul = @Anul
      AND cl.Luna = @Luna
),
TotaluriPeCodPlata AS
(
    SELECT
        CodSucursala,
        CodPlata,

        SUM(
            CASE
                WHEN NetdePlata &amp;gt; 0 THEN NetdePlata
                ELSE 0
            END
        ) AS SumaCasieriPlatitori,

        SUM(NetdePlata) AS SumaCalculLichidare
    FROM Baza
    GROUP BY
        CodSucursala,
        CodPlata
),
DiferenteRaw AS
(
    /*
        Diferențe &#238;ntre totalul listingului Casieri Plătitori
        și totalul complet din Calcul Lichidare.
    */
    SELECT
        1 AS OrdineTip,
        CAST(NULL AS int) AS CalculLichidareId,

        CAST(
            N&#39;DIFERENTA TOTAL COD PLATA&#39;
            AS nvarchar(100)
        ) AS TipDiferenta,

        t.CodPlata,

        COALESCE(
            o.LocPlata,
            N&#39;NECONFIGURAT &#206;N ORGANIGRAMĂ&#39;
        ) AS LocPlata,

        cm.CodCasier,

        CAST(NULL AS nvarchar(450)) AS Marca,
        CAST(NULL AS nvarchar(450)) AS Nume,

        CAST(
            t.SumaCasieriPlatitori
            AS decimal(18, 2)
        ) AS SumaCasieriPlatitori,

        CAST(
            t.SumaCalculLichidare
            AS decimal(18, 2)
        ) AS SumaCalculLichidare,

        CAST(
            t.SumaCasieriPlatitori
            - t.SumaCalculLichidare
            AS decimal(18, 2)
        ) AS Diferenta,

        CAST(NULL AS decimal(18, 2))
            AS NetdePlataNegativ,

        CAST(NULL AS nvarchar(100))
            AS StatusCalcul
    FROM TotaluriPeCodPlata t
    LEFT JOIN CasierMap cm
        ON cm.CodSucursala = t.CodSucursala
       AND cm.CodPlata = t.CodPlata
    LEFT JOIN Organigrama o
        ON o.CodSucursala = t.CodSucursala
       AND o.CodPlata = t.CodPlata
    WHERE ABS(
        t.SumaCasieriPlatitori
        - t.SumaCalculLichidare
    ) &amp;gt; 0.005

    UNION ALL

    /*
        Salariații care au net de plată negativ.
    */
    SELECT
        2 AS OrdineTip,
        b.CalculLichidareId,

        CAST(
            N&#39;NET DE PLATA NEGATIV&#39;
            AS nvarchar(100)
        ) AS TipDiferenta,

        b.CodPlata,

        COALESCE(
            o.LocPlata,
            N&#39;NECONFIGURAT &#206;N ORGANIGRAMĂ&#39;
        ) AS LocPlata,

        cm.CodCasier,
        b.Marca,
        b.Nume,

        CAST(NULL AS decimal(18, 2))
            AS SumaCasieriPlatitori,

        CAST(NULL AS decimal(18, 2))
            AS SumaCalculLichidare,

        CAST(NULL AS decimal(18, 2))
            AS Diferenta,

        b.NetdePlata AS NetdePlataNegativ,

        CAST(
            b.StatusCalcul
            AS nvarchar(100)
        ) AS StatusCalcul
    FROM Baza b
    LEFT JOIN CasierMap cm
        ON cm.CodSucursala = b.CodSucursala
       AND cm.CodPlata = b.CodPlata
    LEFT JOIN Organigrama o
        ON o.CodSucursala = b.CodSucursala
       AND o.CodPlata = b.CodPlata
    WHERE b.NetdePlata &amp;lt; 0
),
Rezultat AS
(
    SELECT
        ROW_NUMBER() OVER
        (
            ORDER BY
                CodPlata,
                OrdineTip,
                Marca,
                CalculLichidareId
        ) AS NrCrt,

        TipDiferenta,
        CodPlata,
        LocPlata,
        CodCasier,
        Marca,
        Nume,
        SumaCasieriPlatitori,
        SumaCalculLichidare,
        Diferenta,
        NetdePlataNegativ,
        StatusCalcul
    FROM DiferenteRaw
)
SELECT
    CAST(NrCrt AS int) AS Id,
    CAST(NrCrt AS int) AS NrCrt,
    TipDiferenta,

    COALESCE(
        CodPlata,
        N&#39;FARA COD PLATA&#39;
    ) AS CodPlata,

    LocPlata,
    CodCasier,
    Marca,
    Nume,
    SumaCasieriPlatitori,
    SumaCalculLichidare,
    Diferenta,
    NetdePlataNegativ,
    StatusCalcul
FROM Rezultat
ORDER BY NrCrt;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;Id
NrCrt
TipDiferenta
CodPlata
LocPlata
CodCasier
Marca
Nume
SumaCasieriPlatitori
SumaCalculLichidare
Diferenta
NetdePlataNegativ
StatusCalcul&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;NrCrt&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;TipDiferenta&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CodPlata&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;LocPlata&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CodCasier&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Marca&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Nume&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;SumaCasieriPlatitori&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;SumaCalculLichidare&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Diferenta&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;NetdePlataNegativ&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;StatusCalcul&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;Nu exista diferente.&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
